CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "274893c2-7895-4fb2-8644-16e05d91c71c",
  "snapshot_timestamp": "2026-05-21T18:10:52Z",
  "ticket_id": "0b6c-08ba",
  "items": [
    {
      "original_text": "A `preplanning.interactive` boolean key (absent or `false` = non-interactive; `true` = interactive) is read at preplanning startup via `read-config.sh` and governs all interactive checkpoints",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system capability where a configuration property governs ongoing interactive behavior at startup"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "In non-interactive mode, all interactive checkpoints have defined non-blocking behavior: invocation without an epic-id exits immediately with a clear error message; scope clarification needed during reconciliation exits immediately with a clear error message identifying what needs clarification; reconciliation approval for existing children is auto-applied; escalation policy defaults to \"Escalate when blocked\" without prompting; story dashboard is suppressed; final story map approval is skipped; ui-designer dispatch protocol (Phase 4 Step 6) uses INTERACTIVITY_DEFERRED paths",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system behavior and properties that persist after implementation, defining how non-interactive mode operates across multiple components"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "`CONFIGURATION-REFERENCE.md` and `workflow-config-schema.json` document `preplanning.interactive` with description, accepted values (true/false), default (non-interactive when absent), per-checkpoint behavior table, and a migration note for existing projects upgrading from always-interactive behavior",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "documentation of a durable system configuration option that will remain part of the system's behavior after completion"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "`/dso:onboarding` asks whether the project should use interactive preplanning and writes `preplanning.interactive` to the generated config accordingly",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability where the config file retains the interactive preplanning setting as an ongoing property"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "This project's `.claude/dso-config.conf` sets `preplanning.interactive=false` explicitly",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a persistent configuration property of the system that remains true after being set"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "An automated preplanning invocation run with `preplanning.interactive` absent or `false` and a valid epic-id completes end-to-end without pausing on any checkpoint \u2014 producing a story map \u2014 confirming the automation-blocking behavior is resolved; tests exercising all six non-interactive checkpoint fallbacks pass",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability (automated preplanning completes without pausing) that persists after the work, verified by passing tests"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When this epic is complete, preplanning runs end-to-end without blocking on any checkpoint when `preplanning.interactive` is absent or false, producing a story map or a structured error exit",
      "original_section": "DD",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior (preplanning runs without blocking) that will remain true after completion, despite the completion-flavored framing"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When this epic is complete, `preplanning.interactive=true` preserves today's interactive behavior at all six checkpoints unchanged",
      "original_section": "DD",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system property (configuration flag behavior) that persists after completion, though the phrasing mixes completion language with ongoing behavioral description"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When this epic is complete, `CONFIGURATION-REFERENCE.md` and `workflow-config-schema.json` document the key with per-checkpoint behavior table and a migration note for existing projects",
      "original_section": "DD",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time documentation update task that will be completed by epic end, not an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    },
    {
      "original_text": "When this epic is complete, `/dso:onboarding` writes `preplanning.interactive` to generated project configs based on the operator's preference",
      "original_section": "DD",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability where the endpoint will persistently write config values based on operator preference, not a one-time migration task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When this epic is complete, this project's `.claude/dso-config.conf` has `preplanning.interactive=false` explicitly set and automated preplanning tests pass",
      "original_section": "DD",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable configuration state and passing test condition that persists after completion, not a one-time task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    }
  ]
}
